export const CREATE_LESSON_PLAN = gql(`
  mutation eduflowCreateLessonPlan(
    $title: String!
    $subject: String!
    $objectives: String
    $goals: String
    $learningObjectives: [String!]
    $content: String
    $materials: String
    $activities: [EduflowActivityStageInput!]
    $childrenParticipation: String
    $differentiation: String
    $assessment: String
    $ageGroup: String
    $duration: Int
    $learningArea: String
    $qualityScore: Int
    $qualityIssues: [String!]
    $source: String
    $attachments: [EduflowAttachmentInput!]
  ) {
    eduflowCreateLessonPlan(
      title: $title
      subject: $subject
      objectives: $objectives
      goals: $goals
      learningObjectives: $learningObjectives
      content: $content
      materials: $materials
      activities: $activities
      childrenParticipation: $childrenParticipation
      differentiation: $differentiation
      assessment: $assessment
      ageGroup: $ageGroup
      duration: $duration
      learningArea: $learningArea
      qualityScore: $qualityScore
      qualityIssues: $qualityIssues
      source: $source
      attachments: $attachments
    ) {
      _id
      title
      status
    }
  }
`);

