export const PRACTICE_QUERY = gql(`
  query eduflowPractice($studentId: String!) {
    eduflowPractice(studentId: $studentId) {
      member {
        _id
        name
        email
        role
        phone
        grade
        avatar
        parentId
        streak
        longestStreak
        points
        lastCompletedDate
      }
      concepts {
        _id
        studentId
        subject
        topic
        mastery
        attempts
        correct
        updatedAt
      }
      activeQuiz {
        ...EduflowQuizFields
      }
      completedQuizzes {
        ...EduflowQuizFields
      }
    }
  }

  fragment EduflowQuizFields on EduflowQuiz {
    _id
    studentId
    subject
    topic
    status
    questions {
      prompt
      options
      difficulty
    }
    currentQuestionIndex
    correctStreak
    bestStreak
    currentDifficulty
    xpEarned
    totalQuestions
    answeredCount
    correctCount
    createdAt
    completedAt
  }
`);

